solution.js:
const alunos = [
  { nome: 'Ana', nota: 9 },
  { nome: 'Bia', nota: 5 },
  { nome: 'Caio', nota: 7 },
  { nome: 'Dudu', nota: 6 },
];

function filtrarAprovados(lista) {
  return lista.filter(function (aluno) {
    return aluno.nota >= 7;
  });
}

const aprovados = document.querySelector('#aprovados');

filtrarAprovados(alunos).forEach(function (aluno) {
  const item = document.createElement('li');
  item.textContent = aluno.nome;
  aprovados.appendChild(item);
});

